📌 Play a Sound for Permission Dialogs
Those dialogs that keep popping up and asking you to click Yes are easy to leave unattended.
I wanted to play a sound when they appeared, but unfortunately, in VSCode + ClaudeCode
, the Notification setting currently does not seem to work properly.
(This is also mentioned in GitHub issues, and it seems to have remained broken since 2.0.8. Incidentally, it does work in the CLI.)
So I decided to implement it using a slightly hacky workaround.
The idea is to hook both the event before a tool runs (such as a bash command) and the event after it runs, then play a sound based on the following logic:
If the pre-execution event fires, but the post-execution event still has not fired after X msec, assume that a dialog is being shown → 🔊Play sound!
Note
The simplest approach would be to play a sound unconditionally whenever the pre-execution event fires.
However, that would also play sounds for commands that run without showing a dialog, which is why this ended up being such a roundabout solution...
📄PowerShell Scripts
📄pretool-resolve.ps1
C:/Users/[user]/.claude/hooks/pretool-resolve.ps1
$log = "$env:USERPROFILE\.claude\hooks\hook-debug.log"
$cfg = "$env:USERPROFILE\.claude\hooks\config.ps1"
$delayed = "$env:USERPROFILE\.claude\hooks\delayed-sound.ps1"
$pendDir = "$env:USERPROFILE\.claude\hooks\pending"
function Write-Log {
param([string]$Message)
"$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') $Message" |
Out-File -FilePath $log -Append -Encoding utf8
}
if (Test-Path -LiteralPath $cfg) {
try { . $cfg } catch { }
}
$sound = $SoundPermission
if (-not $sound) {
Write-Log 'ERROR: not found $SoundPermission in config.ps1'
exit 0
}
$delayMs = if ($DelayMs) { [int]$DelayMs } else { 700 }
function Read-HookInput {
$stdin = [Console]::OpenStandardInput()
$ms = New-Object System.IO.MemoryStream
$stdin.CopyTo($ms)
$raw = [System.Text.Encoding]::UTF8.GetString($ms.ToArray())
return ($raw | ConvertFrom-Json)
}
function Get-AllowPatterns {
param([string]$Cwd)
$allow = New-Object System.Collections.Generic.List[string]
$files = @(
(Join-Path $env:USERPROFILE ".claude\settings.json"),
(Join-Path $Cwd ".claude\settings.json"),
(Join-Path $Cwd ".claude\settings.local.json")
)
foreach ($f in $files) {
if ($f -and (Test-Path -LiteralPath $f)) {
try {
$s = Get-Content -Raw -LiteralPath $f | ConvertFrom-Json
if ($s.permissions -and $s.permissions.allow) {
foreach ($a in $s.permissions.allow) { $allow.Add([string]$a) }
}
} catch { }
}
}
return $allow
}
function Test-NeedsPermission {
param($Tool, $Json, $Allow)
if ($Tool -eq "Bash") {
$cmd = [string]$Json.tool_input.command
if ($null -ne $cmd) { $cmd = $cmd.Trim() }
foreach ($p in $Allow) {
$m = [regex]::Match($p, '^Bash\((.+)\)$')
if (-not $m.Success) { continue }
$inner = $m.Groups[1].Value
if ($inner -eq '*') {
return $false
} elseif ($inner.EndsWith(' *')) {
$prefix = $inner.Substring(0, $inner.Length - 2)
if ($cmd -eq $prefix -or $cmd.StartsWith($prefix + ' ')) { return $false }
} else {
if ($cmd -eq $inner) { return $false }
}
}
return $true
}
foreach ($p in $Allow) {
if ($p -eq $Tool -or $p -eq ($Tool + '(*)')) { return $false }
}
return $true
}
function Start-PendingSound {
param([string]$RawId, [string]$Tool)
$id = if ([string]::IsNullOrEmpty($RawId)) { [guid]::NewGuid().ToString() } else { $RawId }
$id = ($id -replace '[^A-Za-z0-9_\-]', '_')
if (-not (Test-Path -LiteralPath $pendDir)) {
New-Item -ItemType Directory -Force -Path $pendDir | Out-Null
}
$pf = Join-Path $pendDir $id
Get-Date -Format 'yyyy-MM-dd HH:mm:ss' | Out-File -FilePath $pf -Encoding utf8
Write-Log "PreToolUse pending: $Tool id=$id"
Start-Process -FilePath "powershell.exe" `
-ArgumentList @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', "`"$delayed`"", '-Pending', "`"$pf`"", '-Sound', "`"$sound`"", '-DelayMs', $delayMs, '-Id', $id) `
-WindowStyle Hidden | Out-Null
}
try {
$j = Read-HookInput
$tool = [string]$j.tool_name
$cwd = [string]$j.cwd
$allow = Get-AllowPatterns -Cwd $cwd
if (Test-NeedsPermission -Tool $tool -Json $j -Allow $allow) {
Start-PendingSound -RawId ([string]$j.tool_use_id) -Tool $tool
}
} catch {
Write-Log "ERROR(pretool): $_"
}
exit 0
📄posttool-resolve.ps1
C:/Users/[user]/.claude/hooks/posttool-resolve.ps1
$log = "$env:USERPROFILE\.claude\hooks\hook-debug.log"
$pendDir = "$env:USERPROFILE\.claude\hooks\pending"
function Write-Log {
param([string]$Message)
"$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') $Message" |
Out-File -FilePath $log -Append -Encoding utf8
}
function Read-HookInput {
$stdin = [Console]::OpenStandardInput()
$ms = New-Object System.IO.MemoryStream
$stdin.CopyTo($ms)
$raw = [System.Text.Encoding]::UTF8.GetString($ms.ToArray())
return ($raw | ConvertFrom-Json)
}
function ConvertTo-SafeId {
param([string]$Id)
return ($Id -replace '[^A-Za-z0-9_\-]', '_')
}
function Remove-ResolvedMarker {
param([string]$RawId)
if ([string]::IsNullOrEmpty($RawId)) { return }
$id = ConvertTo-SafeId $RawId
$pf = Join-Path $pendDir $id
if (Test-Path -LiteralPath $pf) {
Remove-Item -LiteralPath $pf -Force -ErrorAction SilentlyContinue
Write-Log "PostToolUse resolved (no dialog) id=$id"
}
}
function Clear-OrphanMarkers {
if (-not (Test-Path -LiteralPath $pendDir)) { return }
Get-ChildItem -LiteralPath $pendDir -File -ErrorAction SilentlyContinue |
Where-Object { $_.LastWriteTime -lt (Get-Date).AddSeconds(-120) } |
ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
}
try {
$j = Read-HookInput
Remove-ResolvedMarker -RawId ([string]$j.tool_use_id)
Clear-OrphanMarkers
} catch {
Write-Log "ERROR(posttool): $_"
}
exit 0
📄delayed-sound.ps1
C:/Users/[user]/.claude/hooks/delayed-sound.ps1
param(
[Parameter(Mandatory = $true)][string]$Pending,
[Parameter(Mandatory = $true)][string]$Sound,
[Parameter(Mandatory = $true)][int]$DelayMs,
[string]$Id = ""
)
$log = "$env:USERPROFILE\.claude\hooks\hook-debug.log"
function Write-Log {
param([string]$Message)
"$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') $Message" |
Out-File -FilePath $log -Append -Encoding utf8
}
function Play-Wav {
param([string]$Path)
Add-Type -AssemblyName PresentationCore
$mp = New-Object System.Windows.Media.MediaPlayer
$mp.Volume = 1.0
$mp.Open([System.Uri]::new($Path))
$waited = 0
while (-not $mp.NaturalDuration.HasTimeSpan -and $waited -lt 3000) {
Start-Sleep -Milliseconds 100
$waited += 100
}
if ($mp.NaturalDuration.HasTimeSpan) {
$durMs = [int]$mp.NaturalDuration.TimeSpan.TotalMilliseconds
} else {
$durMs = 4000
}
$mp.Play()
Start-Sleep -Milliseconds ($durMs + 200)
$mp.Stop()
$mp.Close()
return $durMs
}
try {
Start-Sleep -Milliseconds $DelayMs
if (-not (Test-Path -LiteralPath $Pending)) {
Write-Log "delayed-sound SKIPPED (auto-approved, no dialog) id=$Id"
return
}
try { Remove-Item -LiteralPath $Pending -Force -ErrorAction Stop } catch {}
Write-Log "delayed-sound PLAYED (dialog shown) id=$Id"
$durMs = Play-Wav -Path $Sound
Write-Log "delayed-sound OK (dur=${durMs}ms) id=$Id"
} catch {
Write-Log "ERROR(delayed-sound): $_"
}
How It Works
① Route Where a Dialog Appears
Before executing a command that requires dialog confirmation, pretool-resolve.ps1
runs.
⭕ Create a log file in pending/
using the current tool call ID
↓
🎯 Dialog is being shown...
↓
After the command is executed, posttool-resolve.ps1
runs.
❌ If a log file for the current tool call ID exists in pending/
, delete it.
② Route Where No Dialog Appears
Since no dialog appears, the log file is deleted immediately after it is created.
Before executing a command that may require dialog confirmation, pretool-resolve.ps1
runs.
⭕ Create a log file in pending/
using the current tool call ID
↓
After the command is executed, posttool-resolve.ps1
runs.
❌ If a log file for the current tool call ID exists in pending/
, delete it immediately.
Note
pending/
is created automatically.
🔊 delayed-sound.ps1: Playing the Sound
delayed-sound.ps1
plays a sound if the log file for the current tool call ID still exists in pending/
after X msec.
- In case ①, the dialog is shown, so the log file still exists after X msec → 🔊 play sound
- In case ②, the log file is deleted immediately, so it no longer exists after X msec → no sound
This method has one weakness: if the command itself takes X msec or longer to execute, the sound may play even in case ②.
If sounds keep playing even when no dialog is shown, increase $DelayMs
in config.ps1
to adjust the timing.
📌Conclusion
A few additional notes:
- Since the target environment is Windows PowerShell 5.1, save the files as UTF-8 with BOM
- Windows 11 notification settings, such as Focus Assist, may prevent notifications from appearing
I have barely used PowerShell myself, so this was almost entirely done with ClaudeCode.
Depending on your Windows environment, you may need to modify the code.
The PowerShell scripts include error logging, log rotation, and other defensive features, so they may contain extra code if you only want to use the core functionality. Feel free to cut anything you do not need.

When scaling backend architecture, the communication layer between services eventually
becomes a bottleneck. While REST over HTTP/1.1 with JSON payloads is the undisputed
standard for public-facing web APIs, it introduces significant serialization overhead
and lacks strict, enforceable contracts for internal, service-to-service communication.
This is where gRPC shines. By leveraging HTTP/2 for multiplexed transport and Protocol
Buffers (Protobuf) for efficient binary serialization, gRPC provides low-latency,
strictly-typed communication well-suited to internal microservice architectures.
However, gRPC is not a silver bullet. It introduces operational complexity — particularly
around Layer 7 load balancing and debugging binary traffic. This guide strips away the
hype and walks through building a production-ready gRPC client and server in Go, complete
with middleware (interceptors) and server-side streaming.
To make the examples concrete and representative of real-world systems, we will build
a three-tier Pharmacy Inventory service:
┌────────────┐ gRPC ┌──────────────┐ HTTP/JSON ┌──────────────────┐
│ gRPC Client│ ────────────► │ gRPC Server │ ────────────────► │ REST Inventory │
│ (consumer) │ │ :50051 │ │ API :8080 │
└────────────┘ └──────────────┘ └──────────────────┘
This architecture is intentionally realistic: the gRPC layer provides a strict,
typed contract to internal consumers, while delegating actual data retrieval to a
REST backend — exactly as you would find in a system that wraps an existing REST
service or third-party API with a high-performance internal interface.
Prerequisites and Workspace Setup
Ensure your development environment is on a current Go release (1.22 or later, as the
examples use the enhanced net/http
routing patterns introduced in that version). You
will also need the Protocol Buffers compiler (protoc
) and its Go code-generation
plugins.
Install the required Go plugins:
go install google.golang.org/protobuf/cmd/protoc-gen-go@latest
go install google.golang.org/grpc/cmd/protoc-gen-go-grpc@latest
Initialize your module:
mkdir grpc-inventory
cd grpc-inventory
go mod init github.com/murtuza/grpc-inventory
go get google.golang.org/grpc
go get google.golang.org/protobuf
Project Structure
Before writing any code, it helps to see the layout we are building toward:
grpc-inventory/
├── proto/
│ └── inventory.proto # Service contract (single source of truth)
├── proto/inventory/
│ ├── inventory.pb.go # Generated: Protobuf message types
│ └── inventory_grpc.pb.go # Generated: gRPC service interfaces
├── rest-api/
│ └── main.go # REST inventory data layer (:8080)
├── server/
│ └── main.go # gRPC server — calls the REST API (:50051)
├── client/
│ └── main.go # gRPC client — consumes the gRPC server
└── go.mod
Step 1: Defining the Strict Contract (Protobuf)
The foundation of any gRPC service is its interface definition. Protobuf acts as a
strict contract between client and server — if the implementations do not match the
.proto
file, the code will not compile.
Create proto/inventory.proto
:
syntax = "proto3";
package inventory;
option go_package = "github.com/murtuza/grpc-inventory/proto/inventory";
// The Pharmacy Inventory service definition.
service InventoryService {
// Unary RPC: Fetch a single product's stock level.
rpc CheckStock (StockRequest) returns (StockResponse);
// Server-Streaming RPC: Push all items currently running low on stock.
rpc StreamLowStock (EmptyRequest) returns (stream StockResponse);
}
message EmptyRequest {}
message StockRequest {
string sku = 1;
}
message StockResponse {
string sku = 1;
string medicine_name = 2;
int32 quantity = 3;
bool requires_prescription = 4;
}
Generate the Go code from the project root:
protoc --go_out=. --go_opt=paths=source_relative \
--go-grpc_out=. --go-grpc_opt=paths=source_relative \
proto/inventory.proto
This produces two files:
-
proto/inventory/inventory.pb.go
— the generated message structs -
proto/inventory/inventory_grpc.pb.go
— the generated client stub and server interface > Tip: Commit generated.pb.go
files to version control. This makes the schema > auditable in code review and removes theprotoc
toolchain from your CI build path.
Step 2: The REST Inventory API (Data Layer)
Before building the gRPC server, we need the data source it will call. This REST API
represents the inventory database layer — it could equally be an existing internal
service, a third-party API, or a microservice you do not own.
Create rest-api/main.go
:
package main
import (
"encoding/json"
"log"
"net/http"
)
// StockItem mirrors the shape we will return from the REST API.
// The gRPC server will map these fields onto its Protobuf StockResponse.
type StockItem struct {
SKU string `json:"sku"`
MedicineName string `json:"medicine_name"`
Quantity int `json:"quantity"`
RequiresPrescription bool `json:"requires_prescription"`
}
// inventory is the in-memory data store for this service.
// In production this would be replaced by a database query.
var inventory = map[string]StockItem{
"MED-001": {SKU: "MED-001", MedicineName: "Amoxicillin 500mg", Quantity: 1450, RequiresPrescription: true},
"MED-045": {SKU: "MED-045", MedicineName: "Metformin 500mg", Quantity: 320, RequiresPrescription: true},
"MED-089": {SKU: "MED-089", MedicineName: "Ibuprofen 200mg", Quantity: 12, RequiresPrescription: false},
"MED-102": {SKU: "MED-102", MedicineName: "Lisinopril 10mg", Quantity: 5, RequiresPrescription: true},
"MED-201": {SKU: "MED-201", MedicineName: "Cetirizine 10mg", Quantity: 8, RequiresPrescription: false},
}
// lowStockThreshold defines what "low stock" means across the system.
const lowStockThreshold = 50
// writeJSON is a small helper that sets the Content-Type header and encodes
// the provided value as JSON. It writes a 500 if encoding fails.
func writeJSON(w http.ResponseWriter, status int, v any) {
w.Header().Set("Content-Type", "application/json")
w.WriteHeader(status)
if err := json.NewEncoder(w).Encode(v); err != nil {
http.Error(w, `{"error":"encoding failed"}`, http.StatusInternalServerError)
}
}
// getStock handles GET /api/inventory/{sku}.
// It returns the stock record for a single SKU or 404 if not found.
func getStock(w http.ResponseWriter, r *http.Request) {
sku := r.PathValue("sku")
item, ok := inventory[sku]
if !ok {
writeJSON(w, http.StatusNotFound, map[string]string{"error": "SKU not found"})
return
}
writeJSON(w, http.StatusOK, item)
}
// getLowStock handles GET /api/inventory/low-stock.
// It returns all items whose quantity falls below lowStockThreshold.
func getLowStock(w http.ResponseWriter, r *http.Request) {
var items []StockItem
for _, item := range inventory {
if item.Quantity < lowStockThreshold {
items = append(items, item)
}
}
writeJSON(w, http.StatusOK, items)
}
func main() {
mux := http.NewServeMux()
// Register the specific /low-stock route BEFORE the wildcard {sku} route.
// Go 1.22+ ServeMux resolves conflicts by specificity, but explicit ordering
// makes the intent clear to future maintainers.
mux.HandleFunc("GET /api/inventory/low-stock", getLowStock)
mux.HandleFunc("GET /api/inventory/{sku}", getStock)
log.Println("REST Inventory API listening on :8080")
log.Fatal(http.ListenAndServe(":8080", mux))
}
