Step 3: The gRPC Server (Calls the REST API)
The gRPC server fulfils the InventoryService
contract defined in Protobuf. Rather
than owning any data itself, it translates each incoming gRPC call into a corresponding
HTTP request to the REST API, then maps the JSON response onto a Protobuf message.
A shared http.Client
with a connection timeout is created once and reused across all
requests. This is critical — constructing a new http.Client
per request bypasses
Go's built-in connection pooling and introduces unnecessary overhead.
Create server/main.go
:
package main
import (
"context"
"encoding/json"
"fmt"
"log"
"net"
"net/http"
"os"
"time"
pb "github.com/murtuza/grpc-inventory/proto/inventory"
"google.golang.org/grpc"
"google.golang.org/grpc/codes"
"google.golang.org/grpc/status"
)
// restInventoryItem maps the JSON shape returned by the REST API.
type restInventoryItem struct {
SKU string `json:"sku"`
MedicineName string `json:"medicine_name"`
Quantity int `json:"quantity"`
RequiresPrescription bool `json:"requires_prescription"`
}
// server implements the InventoryServiceServer interface.
// Embedding UnimplementedInventoryServiceServer ensures forward compatibility —
// new RPC methods added to the .proto will not break existing server binaries.
type server struct {
pb.UnimplementedInventoryServiceServer
httpClient *http.Client
apiBaseURL string
}
// newServer constructs a server with a shared HTTP client.
// The REST API base URL is read from the REST_API_URL environment variable,
// defaulting to localhost for local development.
func newServer() *server {
baseURL := os.Getenv("REST_API_URL")
if baseURL == "" {
baseURL = "http://localhost:8080"
}
return &server{
httpClient: &http.Client{Timeout: 10 * time.Second},
apiBaseURL: baseURL,
}
}
// fetchItem calls GET /api/inventory/{sku} on the REST API and returns the parsed item.
// It maps HTTP 404 to a gRPC NotFound status so the gRPC client receives a
// well-typed error rather than a raw HTTP error code.
func (s *server) fetchItem(ctx context.Context, sku string) (*restInventoryItem, error) {
url := fmt.Sprintf("%s/api/inventory/%s", s.apiBaseURL, sku)
req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
if err != nil {
return nil, status.Errorf(codes.Internal, "failed to build request: %v", err)
}
resp, err := s.httpClient.Do(req)
if err != nil {
return nil, status.Errorf(codes.Unavailable, "REST API unreachable: %v", err)
}
defer resp.Body.Close()
if resp.StatusCode == http.StatusNotFound {
return nil, status.Errorf(codes.NotFound, "SKU %s not found in inventory", sku)
}
if resp.StatusCode != http.StatusOK {
return nil, status.Errorf(codes.Internal, "REST API returned unexpected status %d", resp.StatusCode)
}
var item restInventoryItem
if err := json.NewDecoder(resp.Body).Decode(&item); err != nil {
return nil, status.Errorf(codes.Internal, "failed to decode REST response: %v", err)
}
return &item, nil
}
// fetchLowStock calls GET /api/inventory/low-stock and returns all matching items.
func (s *server) fetchLowStock(ctx context.Context) ([]restInventoryItem, error) {
url := fmt.Sprintf("%s/api/inventory/low-stock", s.apiBaseURL)
req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
if err != nil {
return nil, status.Errorf(codes.Internal, "failed to build request: %v", err)
}
resp, err := s.httpClient.Do(req)
if err != nil {
return nil, status.Errorf(codes.Unavailable, "REST API unreachable: %v", err)
}
defer resp.Body.Close()
if resp.StatusCode != http.StatusOK {
return nil, status.Errorf(codes.Internal, "REST API returned unexpected status %d", resp.StatusCode)
}
var items []restInventoryItem
if err := json.NewDecoder(resp.Body).Decode(&items); err != nil {
return nil, status.Errorf(codes.Internal, "failed to decode REST response: %v", err)
}
return items, nil
}
// CheckStock is a Unary RPC. It fetches a single SKU from the REST API and
// returns the result as a typed Protobuf message.
func (s *server) CheckStock(ctx context.Context, req *pb.StockRequest) (*pb.StockResponse, error) {
item, err := s.fetchItem(ctx, req.GetSku())
if err != nil {
return nil, err // already a gRPC status error
}
return &pb.StockResponse{
Sku: item.SKU,
MedicineName: item.MedicineName,
Quantity: int32(item.Quantity),
RequiresPrescription: item.RequiresPrescription,
}, nil
}
// StreamLowStock is a Server-Streaming RPC. It fetches all low-stock items from
// the REST API in a single call, then streams each one to the client individually.
func (s *server) StreamLowStock(_ *pb.EmptyRequest, stream pb.InventoryService_StreamLowStockServer) error {
items, err := s.fetchLowStock(stream.Context())
if err != nil {
return err
}
for _, item := range items {
// Respect client cancellation between sends.
if err := stream.Context().Err(); err != nil {
return status.Errorf(codes.Canceled, "client disconnected: %v", err)
}
if err := stream.Send(&pb.StockResponse{
Sku: item.SKU,
MedicineName: item.MedicineName,
Quantity: int32(item.Quantity),
RequiresPrescription: item.RequiresPrescription,
}); err != nil {
return err
}
}
return nil
}
// loggingInterceptor is Unary middleware that records the method, duration,
// and outcome of every incoming RPC call.
func loggingInterceptor(
ctx context.Context,
req interface{},
info *grpc.UnaryServerInfo,
handler grpc.UnaryHandler,
) (interface{}, error) {
start := time.Now()
h, err := handler(ctx, req)
log.Printf("[RPC] method=%s duration=%s err=%v", info.FullMethod, time.Since(start), err)
return h, err
}
func main() {
lis, err := net.Listen("tcp", ":50051")
if err != nil {
log.Fatalf("failed to listen: %v", err)
}
// ChainUnaryInterceptor composes multiple interceptors cleanly.
// Add authInterceptor, recoveryInterceptor, etc. here as the service grows.
s := grpc.NewServer(
grpc.ChainUnaryInterceptor(loggingInterceptor),
)
pb.RegisterInventoryServiceServer(s, newServer())
log.Printf("Inventory gRPC server listening at %v", lis.Addr())
if err := s.Serve(lis); err != nil {
log.Fatalf("failed to serve: %v", err)
}
}
Step 4: The gRPC Client
The client connects to the gRPC server and exercises both RPC patterns — a unary call
and a server-streaming call.
The traditional grpc.Dial
is deprecated in modern versions of grpc-go
. Its
replacement, grpc.NewClient
, provides a more robust API and establishes the underlying
connection lazily on the first RPC call rather than at construction time.
Create client/main.go
:
package main
import (
"context"
"io"
"log"
"time"
pb "github.com/murtuza/grpc-inventory/proto/inventory"
"google.golang.org/grpc"
"google.golang.org/grpc/credentials/insecure"
)
func main() {
// grpc.NewClient does not block — the connection is established lazily.
// For production, replace insecure.NewCredentials() with a TLS config.
conn, err := grpc.NewClient(
"localhost:50051",
grpc.WithTransportCredentials(insecure.NewCredentials()),
)
if err != nil {
log.Fatalf("could not create client: %v", err)
}
defer conn.Close()
c := pb.NewInventoryServiceClient(conn)
testUnaryCall(c)
testStreamingCall(c)
}
func testUnaryCall(c pb.InventoryServiceClient) {
// A deadline context is essential for unary calls. Without one, a slow or
// unresponsive server will block the caller indefinitely.
ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
defer cancel()
log.Println("--- Executing Unary RPC ---")
r, err := c.CheckStock(ctx, &pb.StockRequest{Sku: "MED-001"})
if err != nil {
log.Fatalf("CheckStock failed: %v", err)
}
log.Printf("Stock check -> %s: %d units (prescription required: %t)",
r.GetMedicineName(), r.GetQuantity(), r.GetRequiresPrescription())
}
func testStreamingCall(c pb.InventoryServiceClient) {
log.Println("\n--- Executing Server-Streaming RPC ---")
// A deadline is equally important on streaming calls. Use context.WithCancel
// if you need to abort the stream from the client side based on your own logic.
ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
defer cancel()
stream, err := c.StreamLowStock(ctx, &pb.EmptyRequest{})
if err != nil {
log.Fatalf("StreamLowStock failed: %v", err)
}
for {
item, err := stream.Recv()
if err == io.EOF {
// The server closed the stream normally.
break
}
if err != nil {
log.Fatalf("error receiving from stream: %v", err)
}
log.Printf("ALERT: Low stock -> %s (SKU: %s) has only %d units remaining.",
item.GetMedicineName(), item.GetSku(), item.GetQuantity())
}
log.Println("--- Stream complete ---")
}
Step 5: Running the Full Stack
The three services run independently. Open three terminals from the project root.
Terminal 1 — Start the REST API:
go run rest-api/main.go
# REST Inventory API listening on :8080
Terminal 2 — Start the gRPC server:
go run server/main.go
# Inventory gRPC server listening at [::]:50051
Terminal 3 — Run the gRPC client:
go run client/main.go
Expected client output:
--- Executing Unary RPC ---
Stock check -> Amoxicillin 500mg: 1450 units (prescription required: true)
--- Executing Server-Streaming RPC ---
ALERT: Low stock -> Ibuprofen 200mg (SKU: MED-089) has only 12 units remaining.
ALERT: Low stock -> Lisinopril 10mg (SKU: MED-102) has only 5 units remaining.
ALERT: Low stock -> Cetirizine 10mg (SKU: MED-201) has only 8 units remaining.
--- Stream complete ---
Meanwhile, Terminal 2 (the gRPC server) will emit interceptor logs for each call:
[RPC] method=/inventory.InventoryService/CheckStock duration=2.1ms err=<nil>
[RPC] method=/inventory.InventoryService/StreamLowStock duration=1.8ms err=<nil>
Configuring the REST API URL
The gRPC server reads its upstream address from the REST_API_URL
environment
variable, which defaults to http://localhost:8080
if unset. To point it at a
different host (e.g. in a Docker Compose network):
REST_API_URL=http://inventory-api:8080 go run server/main.go
Step 6: Debugging Binary Traffic with grpcurl
One of gRPC's stated drawbacks is that binary Protobuf payloads are opaque to
standard HTTP tools like curl
. The idiomatic solution is
grpcurl
— a command-line tool that
speaks gRPC natively, playing the same role curl
plays for REST APIs.
Install it:
go install github.com/fullstorydev/grpcurl/cmd/grpcurl@latest
To use grpcurl
without a .proto
file, enable server reflection by adding two
lines to server/main.go
:
import "google.golang.org/grpc/reflection"
// Inside main(), after pb.RegisterInventoryServiceServer:
reflection.Register(s)
Security note: Only enable reflection in development and staging environments.
Exposing your full service schema in production is an unnecessary attack surface.
With reflection running, you can introspect and invoke your service from the terminal,
in exactly the same workflow as curl + a REST API:
# List all available services
grpcurl -plaintext localhost:50051 list
# Describe the full InventoryService schema
grpcurl -plaintext localhost:50051 describe inventory.InventoryService
# Call CheckStock (unary)
grpcurl -plaintext \
-d '{"sku": "MED-001"}' \
localhost:50051 inventory.InventoryService/CheckStock
# Stream low-stock alerts (server-streaming)
grpcurl -plaintext \
-d '{}' \
localhost:50051 inventory.InventoryService/StreamLowStock
Production Considerations
TLS
The examples above use insecure.NewCredentials()
, transmitting data in plaintext.
For any non-local deployment, use mutual TLS (mTLS):
// Server-side
creds, err := credentials.NewServerTLSFromFile("server.crt", "server.key")
s := grpc.NewServer(grpc.Creds(creds), ...)
// Client-side
creds, err := credentials.NewClientTLSFromFile("ca.crt", "")
conn, err := grpc.NewClient("host:50051", grpc.WithTransportCredentials(creds))
Chaining Multiple Interceptors
Real services need more than logging. Authentication, rate limiting, and panic recovery
are all common interceptor concerns. grpc.ChainUnaryInterceptor
composes them
without nesting:
s := grpc.NewServer(
grpc.ChainUnaryInterceptor(
loggingInterceptor,
authInterceptor,
recoveryInterceptor,
),
grpc.ChainStreamInterceptor(
streamLoggingInterceptor,
),
)
grpc.UnaryInterceptor
only accepts a single function and panics if called more
than once — always prefer ChainUnaryInterceptor
in production code.
HTTP Client Timeouts
The gRPC server's http.Client
is configured with a 10-second timeout, but you
may want to tune this per-call using the incoming gRPC context directly, so that
a client's deadline propagates end-to-end:
// Pass the gRPC call context into the downstream HTTP request.
// If the gRPC client cancels, the REST API call is cancelled too.
req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
This pattern is already used in the server code above and prevents a situation where
a gRPC client times out but the REST API call continues to consume resources on the
server.
Architectural Realities: When (and When Not) to Use gRPC
While gRPC's performance characteristics are compelling, engineering is about
trade-offs.
Where gRPC Excels
Polyglot microservices. If your backend spans Go, Rust, Python, and Node.js,
Protobuf generates idiomatic client libraries for all of them from a single .proto
source of truth — with no per-language schema drift.
High-throughput internal APIs. Binary serialization is measurably faster to encode
and decode than JSON, and Protobuf payloads are significantly smaller over the wire —
particularly important at high request volumes.
Strict typing as a contract. Runtime errors caused by a misspelled JSON field
become a compile-time failure. The contract is enforced at build time, not discovered
in production.
Bidirectional streaming. gRPC supports client streaming, server streaming, and
full-duplex bidirectional streaming out of the box — capabilities that require
WebSockets or SSE to replicate in a REST architecture.
The Pragmatic Drawbacks
Layer 7 load balancing. Because gRPC multiplexes requests over long-lived HTTP/2
TCP connections, standard L4 load balancers (such as AWS NLB or a default Kubernetes
Service
) will funnel all traffic from a single client pod to one server pod,
defeating horizontal scaling. You must front gRPC services with an L7 proxy — Envoy,
NGINX, or a full service mesh like Istio — to distribute load at the request level.
Browser incompatibility. Web browsers cannot natively initiate the HTTP/2
connections gRPC requires. Calling a gRPC service from a browser requires grpc-web
and an Envoy proxy as a translation layer. If your primary consumers are web or mobile
frontends, REST or GraphQL is architecturally simpler.
Operational tooling curve. Teams accustomed to curl
, Postman, and browser
DevTools will need to adopt grpcurl
or Postman's gRPC mode. Binary traffic is
invisible without the right tools in place — which is precisely why the grpcurl
section above is not optional reading.
Summary
This guide built a realistic three-tier system: a REST data layer verified directly
with curl
, a gRPC server that calls it, and a typed gRPC client that consumes the
result. Each tier can be developed, tested, and debugged in isolation — the REST API
with curl
, and the gRPC surface with grpcurl
.
gRPC in Go provides a robust foundation for enterprise-grade internal services, but it
should be adopted rationally. Use it where strict contracts, low latency, and efficient
serialization are genuine architectural requirements — not merely because it is the
current industry trend.
The full source code for this tutorial is available at
github.com/mmurtuza/grpc-inventory.
Engineering is best when shared. Find more of my writing, projects, and work at -- murtuza.dev

The release of nest-drizzle-native 0.2.1 introduces a community package designed to make Drizzle ORM feel entirely natural inside NestJS applications.
The core concept is straightforward: preserve Drizzle's explicit, SQL-first philosophy while giving NestJS projects the module, dependency injection, repository, testing, and transaction ergonomics they expect.
The Motivation
Drizzle is excellent because it stays close to SQL and avoids heavy, opaque ORM magic.
NestJS, on the other hand, provides applications with a strong architectural shape built around modules, providers, decorators, testing utilities, lifecycle hooks, and clear dependency boundaries.
A bridge between those two worlds allows teams to build scalable enterprise architectures without turning Drizzle into something it is not. Existing solutions often act as thin connection wrappers, leaving developers to manually solve complex enterprise patterns like cross-service transactions or DTO co-generation.
What it supports today
-
DrizzleModule.forRoot()
,forRootAsync()
, andforFeature()
-
@InjectDrizzle()
for direct Drizzle client injection -
@DrizzleRepository()
for query-focused provider classes -
@Transactional()
/@InjectTransaction()
powered natively via@nestjs-cls/transactional
- Named connections for multi-database applications
- Testing utilities for clean module and repository testing
- Zero runtime dependencies in the published library package
- Runnable samples covering transactions, DTO validation, optional
drizzle-zod
validation, Swagger/OpenAPI integration, raw SQL execution, and various driver setups
Let's look at the code
The biggest pain point of using Drizzle in a structured backend is transaction management. Passing a tx
object through five layers of injected services completely breaks Dependency Injection.
With nest-drizzle-native
, transactions are managed via Node.js AsyncLocalStorage
, allowing them to flow seamlessly across your services just by using a decorator:
import { eq } from 'drizzle-orm';
import {
DrizzleRepository,
InjectDrizzle,
} from 'nest-drizzle-native';
import type { AppDatabase } from './database';
import { users } from './schema';
@DrizzleRepository()
export class UsersRepository {
constructor(@InjectDrizzle() private readonly db: AppDatabase) {}
async findById(id: string) {
const [user] = await this.db
.select()
.from(users)
.where(eq(users.id, id))
.limit(1);
return user;
}
async insert(data: CreateUserDto) {
const [user] = await this.db
.insert(users)
.values(data)
.returning();
return user;
}
}
The repository itself is a clean Nest provider that keeps Drizzle's query builder visible instead of hiding SQL behind an Active Record layer:
import { eq } from 'drizzle-orm';
import {
DrizzleRepository,
InjectDrizzle,
} from 'nest-drizzle-native';
import type { AppDatabase } from './database';
import { users } from './schema';
@DrizzleRepository()
export class UsersRepository {
constructor(@InjectDrizzle() private readonly db: AppDatabase) {}
async findById(id: string) {
const [user] = await this.db
.select()
.from(users)
.where(eq(users.id, id))
.limit(1);
return user;
}
}
What it does not try to do
The goal is strictly avoiding the re-creation of TypeORM or an Active Record layer.
Developers still write real, functional Drizzle queries. The library simply provides those queries with a native NestJS structure through decorators and context management, eliminating the need to pass transaction callbacks (tx
) down through multiple layers of services.
Links
- Docs: https://nest-native.github.io/nest-drizzle-native/
- GitHub: https://github.com/nest-native/nest-drizzle-native
- npm: https://www.npmjs.com/package/nest-drizzle-native
- Release: https://github.com/nest-native/nest-drizzle-native/releases/tag/nest-drizzle-native%400.2.1
Community feedback from NestJS and Drizzle users is highly encouraged—especially regarding real-world transaction patterns, testing strategies, multi-database setups, and production adoption. Feel free to open issues or contribute to the repository!

The N+1 problem happens when:
Hibernate executes 1 query to fetch parent records
+
N additional queries to fetch child records
This causes:
- too many database calls
- performance degradation
- slow APIs
The Hibernate N+1 problem occurs when Hibernate executes one query
to fetch parent entities and then executes additional queries for
each associated child entity due to lazy loading. This leads to
excessive database round trips and performance degradation. The
most common solution is using JOIN FETCH, EntityGraph, batch
fetching, or DTO projections to load related data efficiently in
fewer queries.
Simple Real-World Example
Suppose: 100 customers each customer has N orders
You want: all customers with their orders
But Hibernate executes:
1 query for customers
100 separate queries for orders
Total: 101 queries
This is: N+1 problem
1. Customer Entity
package com.example.entity;
import jakarta.persistence.*;
import lombok.*;
import java.util.List;
@Entity
@Table(name = "customers")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@ToString(exclude = "orders")
public class Customer {
@Id
@GeneratedValue(strategy = GenerationType.IDENTITY)
private Long id;
private String name;
@OneToMany(
mappedBy = "customer",
fetch = FetchType.LAZY,
cascade = CascadeType.ALL
)
private List<Order> orders;
}
2. Order Entity
package com.example.entity;
import jakarta.persistence.*;
import lombok.*;
@Entity
@Table(name = "orders")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@ToString(exclude = "customer")
public class Order {
@Id
@GeneratedValue(strategy = GenerationType.IDENTITY)
private Long id;
private String item;
@ManyToOne(fetch = FetchType.LAZY)
@JoinColumn(name = "customer_id")
private Customer customer;
}
Important Thing FetchType.LAZY
means:
- orders NOT loaded immediately
- loaded only when accessed
The Problematic Code
List<Customer> customers = customerRepository.findAll();
for(Customer c : customers) {
System.out.println(c.getOrders().size());
}
Looks harmless. BUT internally dangerous.
What Happens Internally?
Query 1 : Hibernate fetches customers:
SELECT * FROM customer;
Suppose 100 customers returned.
Then Loop Starts Iteration 1 c.getOrders()
Triggers:
SELECT * FROM orders WHERE customer_id = 1;
Iteration 2
SELECT * FROM orders WHERE customer_id = 2;
Final Total 1 + N queries
If: 100 customers then: 101 queries
Visual Representation
Initial Query
SELECT customers
returns:
C1 C2 C3 C4 C5
Then Lazy Loading
C1 → SELECT orders
C2 → SELECT orders
C3 → SELECT orders
C4 → SELECT orders
C5 → SELECT orders
Many DB round trips. Why Is This Bad?
Database calls are expensive.
Problems:
- network latency
- DB CPU usage
- connection pool pressure
- slow response times
How To Detect N+1 Problem Enable SQL logging.
Spring Boot
spring.jpa.show-sql=true
If you see: repeated similar queries
then likely N+1 issue.
Solution 1. FETCH JOIN
package com.example.repository;
import com.example.entity.Customer;
import org.springframework.data.jpa.repository.*;
import org.springframework.stereotype.Repository;
import java.util.List;
@Repository
public interface CustomerRepository
extends JpaRepository<Customer, Long> {
@Query("""
SELECT DISTINCT c
FROM Customer c
JOIN FETCH c.orders
""")
List<Customer> findAllCustomersWithOrders();
}
What Happens Now? Hibernate executes ONE query:
SELECT c.*, o.*
FROM customer c
JOIN orders o
ON c.id = o.customer_id;
Result Instead of: 101 queries Only: 1 query
Huge improvement.
Visual
Before
1 customer query + 100 order queries
After FETCH JOIN 1 combined query
2. EntityGraph
@EntityGraph(attributePaths = "orders")
List<Customer> findAll();
Tells Hibernate: load orders together
Advantage : Cleaner than custom JPQL sometimes.
3. Batch Fetching - Hibernate optimization.
Example
spring.jpa.properties.hibernate.default_batch_fetch_size=20
What Happens? Instead of: 100 queries Hibernate batches:
SELECT * FROM orders
WHERE customer_id IN (1,2,3...20)
Much fewer queries.
4. DTO Projection - Best for read-heavy APIs.
Example
@Query("""
SELECT new com.dto.CustomerDTO(
c.name,
o.item)
FROM Customer c
JOIN c.orders o
""")
Avoids entity graph entirely. Very efficient.
** Service Class**
package com.example.service;
import com.example.entity.Customer;
import com.example.repository.CustomerRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import java.util.List;
@Service
@RequiredArgsConstructor
public class CustomerService {
private final CustomerRepository customerRepository;
public void printCustomers() {
List<Customer> customers =
customerRepository
.findAllCustomersWithOrders();
for(Customer c : customers) {
System.out.println(c.getName());
System.out.println(c.getOrders().size()
);
}
}
}
Interview Question
Q1. Why Not Use EAGER Fetching?
Many thinks: FetchType.EAGER
solves N+1 but NOT always true.
Why?
EAGER can STILL produce N+1.
And may:
- load unnecessary data
- create huge joins
hurt performance
Example Suppose:Customer
Orders
Payments
Addresses
EAGER loading everything creates:
Cartesian product explosion
massive memory usage
Best Practice Prefer:
LAZY + FETCH JOIN when needed
Q2. Why LAZY Exists If It Causes N+1?
Because:
loading everything always is worse
sometimes child data not needed
LAZY improves:
memory usage
startup cost
flexibility
Problem occurs only when: iterative lazy access happens
Another Dangerous Situation
Nested N+1.
Example
Customer → Orders → Items
Now queries become:
1 + N + N*M
Can explode massively.
Important Hibernate Internals
N+1 happens because:
- Hibernate proxy objects
- lazy initialization
- session-triggered fetch
- Lazy Loading Mechanism
Hibernate initially creates:proxy objects
Actual SQL executed only when accessed.
Example c.getOrders()
This line triggers DB query.
Best Solutions Comparison
Solution Best For
FETCH JOIN Most common
EntityGraph Clean JPA
Batch Fetching Large collections
DTO Projection APIs/reporting
Q3. Does N+1 happen only in OneToMany?
NO. Can happen in:
- ManyToOne
- OneToOne
- nested associations

AI is evolving beyond simple text interactions toward rich multimodal capabilities, such as on-device image and audio generation, enabling developers to create highly personalized consumer experiences. While the CPU has always been the ubiquitous option for inference, running large complex models at the edge has historically required choosing between high-latency CPU execution and fragmented, specialized accelerators.
Arm Scalable Matrix Extension 2 (SME2) eliminates this tradeoff by integrating a dedicated matrix-compute unit directly into the CPU cluster. This architecture enables the CPU to function as a high-performance AI accelerator, delivering up to 5x faster inference for the matrix-heavy workloads at the heart of generative AI.
Running on-device AI on Arm hardware is dramatically streamlined with Google AI Edge, an integrated stack designed to simplify your development journey. LiteRT automatically leverages Arm SME2 at runtime through XNNPACK and Arm KleidiAI integration. It identifies and selects math-intensive kernels like iGeMM and GeMM, delivering specialized hardware acceleration. To further ease deployment, AI Edge Quantizer handles complex model compression, and Model Explorer provides a visual map to quickly identify and resolve performance hotspots.
The power of this integration is proven through deploying Stability AI’s stable-audio-open-small model entirely on Arm CPUs delivering major performance uplift. In this blog post, we’ll walk you through transforming the original floating-point PyTorch stable-audio-open-small model into a highly optimized, mixed-precision (FP16/Int8) implementation ready for high-performance acceleration on Arm CPU.
Link to Youtube Video (visible only when JS is disabled)
To generate high-quality audio, such as 11-second stereo clips from a single prompt, directly on a wide range of mobile devices, practical considerations usually require a manageable model footprint, typically around 1 billion parameters. Even within this Small Language Model (SLM) range, developers face Challenging Deployment Hurdles:
By using a diffusion-based model as the optimization target, we demonstrate a complete end-to-end path with the Google AI Edge software stack. As shown below, this synergy provides a streamlined Convert → Optimize → Deploy pipeline.
Given the KleidiAI optimizations are embedded directly into XNNPACK, developers gain specialized AI acceleration automatically. There is no need to write low-level assembly or custom hardware code; the stack handles the "translation" from high-level model to silicon-optimized execution.
Start by converting the PyTorch version of the Stable-audio-open-small model into the AI Edge ecosystem. LiteRT-Torch allows for a direct conversion path for PyTorch models, minimizing friction of moving from a research environment to a production mobile environment.
import litert_torch
from litert_torch.quantize import quant_config
from litert_torch.generative.quantize import quant_recipe, quant_recipe_utils
# Specify the quantization format
quant_config_int8 = quant_config.QuantConfig(
generative_recipe=quant_recipe.GenerativeQuantRecipe(
default=quant_recipe_utils.create_layer_quant_dynamic(),
)
)
# Initiate the conversion
edge_model = ai_edge_torch.convert(
model, example_inputs, quant_config=quant_config_int8
)
Find the code snippet to illustrate how LiteRT-Torch works in practice here
Previously, identifying which layers of a model were suitable for quantization was a manual, error-prone process of inspecting individual layers.
With Google’s Model Explorer, developers can now visualize the entire model graph. The new node data overlay plugin allows us to see exactly which operators are most compute-intensive or as shown below which are "quantization-safe". This visual verification ensures we only target layers where moving to INT8 won't degrade audio output quality.
For example, to improve the inference efficiency of the diffusion step, we applied dynamic INT8 quantization to the DiT (Diffusion Transformers) submodule:
As shown in the screenshot above, all layers in the DiT submodule are green, indicating low error values within the DiT transformer (FP32 vs. FP32+INT8). Therefore, we expect the dynamically quantized INT8 DiT submodule to achieve quality comparable to FP32.
Once the suitability of INT8 quantization was confirmed, we utilized the AI Edge Quantizer to optimize the model from FP32 to INT8.
This decision resulted in 3x performance improvement in the DiT submodule, along with a 4x reduction of its memory usage.
fp32_model_path = "./dit_model_fp32.tflite"
dynamic_quant_model_path = "./dit_model_int8+fp32.tflite"
the_recipe = [
dict({
'regex': '.*',
'operation': '*',
'algorithm_key': 'min_max_uniform_quantize',
'op_config': {
'weight_tensor_config': {
'num_bits': 8,
'symmetric': True,
'granularity': 'CHANNELWISE',
'dtype': 'INT',
'block_size': 0,
},
'compute_precision': 'INTEGER',
'explicit_dequantize': False,
'skip_checks': False,
'min_weight_elements': 0
},
})
]
# Define the quantizer, with fp32 tflite model, and the recipe.
qt = quantizer.Quantizer(fp32_model_path, the_recipe)
quant_result = qt.quantize().export_model(dynamic_quant_model_path, overwrite=True)
The final step is the runtime.
When you run this quantized model in LiteRT on an Android mobile device, it defaults to the XNNPACK delegate for CPU inference. Because XNNPACK integrates KleidiAI directly within the latest LiteRT API, developers get these optimizations automatically. These micro-kernels ensure that the core INT8 and FP16 matrix multiplications of the audio model run with maximum efficiency on the CPU.
Below is a representative snippet of how LiteRT inference is implemented in C++ using the CompiledModel API. Instructions in this guide are provided for running the audiogen app with LiteRT either on an Android™ device or macOS®.
#include "litert/cc/litert_compiled_model.h"
#include "litert/cc/litert_environment.h"
#include "litert/cc/litert_tensor_buffer.h"
// 1. Initialize the LiteRT Environment
auto env = litert::Environment::Create({}).value();
// 2. Create the CompiledModel from the .tflite file
// Hardware acceleration (e.g., SME2 via KleidiAI) is handled automatically
auto compiled_model = litert::CompiledModel::Create(
env, "autoencoder_model.tflite", litert::HwAccelerators::kCpu).value();
// 3. Prepare input and output buffers
auto autoencoder_inputs = compiled_model.CreateInputBuffers().value();
auto autoencoder_outputs = compiled_model.CreateOutputBuffers().value();
// 4. Write input data (e.g., random noise or conditioned embeddings)
auto auto_in_lock_and_ptr = scoped_lock<float>(autoencoder_inputs[0],
litert::TensorBuffer::LockMode::kWrite);
// Fill the input
// 5. Execute inference
compiled_model.Run(autoencoder_inputs, autoencoder_outputs);
// 6. Access and read the generated audio waveform from the output buffer
auto auto_out_lock_and_ptr = scoped_lock<const float>(autoencoder_outputs[0], litert::TensorBuffer::LockMode::kRead);
// Read the output
We now take our quantized fp16/int8 model from the prior section and benchmark both CPU single threaded and multi-threaded (MT) performance with the original FP32 Stable Audio Open Small model against our KleidiAI-optimized FP16 + INT8 model on an SME2-based Android device and on an Apple MacBook with M4.
As shown in the bar chart above, SME2 delivers more than a 2x performance improvement over the NEON instruction set, specialized for signal processing tasks. Even with a single core, it can generate 11 seconds of audio in under 8 seconds, which is acceptable from a user-experience perspective.
These optimizations are available for developers today. Start experimenting immediately using Google AI Edge tools and KleidiAI-accelerated LiteRT.
